import { expect, test, type Page } from "@playwright/test";
import { existsSync, mkdirSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: 8 s and 1 s vertical clips.
const LONG = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const SHORT = path.resolve("fixtures", "short_1s.mp4");
const PRODUCT = "Levi's 501 Jeans";

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(
    !existsSync(LONG) || !existsSync(SHORT),
    'Run "npm run fixtures" first.',
  );
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

async function shot(name: string) {
  mkdirSync("test-results", { recursive: true });
  await page.screenshot({ path: path.join("test-results", `e2e-${name}.png`) });
}

// Quit and start the same app again (same userData and library).
async function relaunch() {
  await launched.app.close();
  launched = await launchPackagedApp(launched);
  page = await launched.app.firstWindow();
}

const nav = (name: string) =>
  page.getByRole("button", { name, exact: true }).first().click();
const slot = (name: "before" | "after" | "broll") =>
  page.getByTestId(`slot-${name}`);

test("build a draft, restart, close it, and find it in History", async () => {
  await test.step("pick a library, add a product and one b-roll clip", async () => {
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(PRODUCT);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
    await page
      .getByRole("listitem")
      .filter({ hasText: PRODUCT })
      .getByRole("button", { name: new RegExp(PRODUCT) })
      .first()
      .click();
    await page.getByLabel("B-roll files").setInputFiles([LONG]);
    await expect(page.getByTestId("broll-duration")).toHaveCount(1, {
      timeout: 60_000,
    });
  });

  await test.step("New Video shows the product grid; picking opens an empty editor", async () => {
    await nav("New Video");
    await page.getByRole("option", { name: new RegExp(PRODUCT) }).click();
    await expect(slot("before")).toHaveAttribute("data-status", "empty");
    await expect(slot("after")).toHaveAttribute("data-status", "empty");
    await expect(slot("broll")).toHaveAttribute("data-status", "empty");
    await shot("editor-empty");
  });

  await test.step("an untouched draft is not listed in History", async () => {
    await nav("History");
    await expect(page.getByText("No drafts yet")).toBeVisible();
    await nav("New Video");
    await expect(slot("before")).toBeVisible();
  });

  await test.step("importing Before and After fills the cards", async () => {
    await page.getByLabel("Before clip file").setInputFiles([LONG]);
    await page.getByLabel("After clip file").setInputFiles([SHORT]);
    await expect(slot("before")).toHaveAttribute("data-status", "ready", {
      timeout: 60_000,
    });
    await expect(slot("after")).toHaveAttribute("data-status", "ready", {
      timeout: 60_000,
    });
    // 8 s clip, 3 s default: "3.0s of 8.0s". 1 s clip is shorter than its 4 s default.
    await expect(slot("before")).toContainText("3.0s of 8.0s");
    await expect(slot("after")).toContainText("1.0s");
    await expect(slot("after")).not.toContainText(" of ");
    await expect(slot("before").locator("img")).toHaveJSProperty(
      "complete",
      true,
    );
  });

  await test.step("picking b-roll fills the third card", async () => {
    await slot("broll").getByRole("button", { name: "Choose b-roll" }).click();
    const picker = page.getByRole("dialog");
    await picker.getByRole("option").first().click();
    await expect(slot("broll")).toHaveAttribute("data-status", "ready");
    await shot("editor-full");
  });

  await test.step("the draft is listed in History", async () => {
    await nav("History");
    const row = page.getByTestId("draft-row");
    await expect(row).toHaveCount(1);
    await expect(row).toContainText(PRODUCT);
    await expect(row).toContainText("3 of 3 clips");
  });

  await test.step("after a restart the open draft is back", async () => {
    await relaunch();
    await expect(slot("before")).toHaveAttribute("data-status", "ready", {
      timeout: 30_000,
    });
    await expect(slot("after")).toHaveAttribute("data-status", "ready");
    await expect(slot("broll")).toHaveAttribute("data-status", "ready");
    await expect(slot("before")).toContainText("3.0s of 8.0s");
    await expect(slot("before").locator("img")).toHaveJSProperty(
      "complete",
      true,
    );
    await shot("editor-restored");
  });

  await test.step("Close draft, restart: the grid shows and the draft is still in History", async () => {
    await page.getByRole("button", { name: "Close draft" }).click();
    await expect(page.getByRole("listbox", { name: "Products" })).toBeVisible();
    await relaunch();
    // Nothing was open, so the app starts on Products and New Video shows the grid.
    await nav("New Video");
    await expect(page.getByRole("listbox", { name: "Products" })).toBeVisible();
    await expect(slot("before")).toHaveCount(0);
    await nav("History");
    await expect(page.getByTestId("draft-row")).toHaveCount(1);
  });

  await test.step("Open from History brings the draft back", async () => {
    await page.getByRole("button", { name: "Open" }).click();
    await expect(slot("before")).toHaveAttribute("data-status", "ready");
    await expect(slot("broll")).toHaveAttribute("data-status", "ready");
  });

  await test.step("a changed default length applies to the next draft", async () => {
    await page.getByRole("button", { name: "Close draft" }).click();
    await nav("Settings");
    await page.getByLabel("Before length").fill("2");
    await page.getByRole("button", { name: "Save defaults" }).click();
    await expect(page.getByRole("status")).toHaveText("Saved.");
    await nav("New Video");
    await page.getByRole("option", { name: new RegExp(PRODUCT) }).click();
    // 2 + 4 + 5
    await expect(page.getByTestId("total-length")).toHaveText("11.0s");
  });

  await test.step("deleting a draft in History removes it", async () => {
    await page.getByRole("button", { name: "Close draft" }).click();
    await nav("History");
    await page.getByRole("button", { name: "Delete" }).click();
    const dialog = page.getByRole("dialog", { name: "Delete draft" });
    await dialog.getByRole("button", { name: "Delete" }).click();
    await expect(dialog).toBeHidden();
    await expect(page.getByText("No drafts yet")).toBeVisible();
  });
});
